/**
 * 画师列表取数：直接拿 infos.json 与 illvariants.json 在浏览器里现算
 * （和谱师列表一样，不再有预生成文件）。
 *
 * 分组逻辑在 illustratorGroup.js，这里只负责取数、给每一版曲绘补上图片地址。
 * 两份 JSON 都走 jsonCache 的请求缓存，多一个页面不会重复下载。
 */
import { loadJson } from './jsonCache.js'
import { illLowPath } from './common.js'
import { groupByIllustrator } from './illustratorGroup.js'

export async function getIllustratorGroups() {
  try {
    const [songData, illVariants] = await Promise.all([
      loadJson('/files/infos/infos.json'),
      loadJson('/files/infos/illvariants.json')
    ])
    const grouped = groupByIllustrator(songData, illVariants)
    for (const items of Object.values(grouped)) {
      for (const item of items) item.cover = illLowPath(item.songId, item.ill)
    }
    return grouped
  } catch (error) {
    console.error('获取画师数据失败：', error)
    return {}
  }
}
