/**
 * 把 infos.json 按画师拆成分组数据（和谱师列表同一套思路：浏览器里现算，不预生成 JSON）。
 *
 * 每组是一张卡：同一首歌的现用曲绘、历史曲绘（-1 / -2）和差分曲绘（1 / 2 / 3）
 * 各算一条，因为它们的画师可能不是同一个人 —— 这些署名在 illvariants.json 里。
 * 没有多版曲绘的曲目直接用 infos.json 的「画师名义 / 画师」。
 *
 * 结构：「画师 → [{ songId, name, illustrator, artist, ill }]」，
 * 画师按名字排序（规则见 api/nameSort.js）、每位画师下的条目按曲名、再按曲绘版本排序。
 */

import { compareNames } from './nameSort.js'

/** 画师列没填、只剩版本占位符的格子（如「①②④⑨」），不当作画师 */
const PLACEHOLDER = /[①②③④⑤⑥⑦⑧⑨⑩]/

/**
 * 同一首曲拆出来的字母版条目（Random [R] / [A] / [N] / [D] / [O] / [M]），
 * 画师列表里只列 .0 的那一版，不然同一位画师会排出一串几乎一样的卡。
 */
const HIDDEN_SONG_ID = /^Random\.SobremSilentroom\.[1-9]$/

/**
 * 旧曲绘和现用曲绘是同一张图的，列表里不再单独列。
 * Pixel Rebelz 的 .-1 与大图 .0 完全一样（换了一圈又换回来），只差低清重压的字节。
 */
const REPEATED_ART = { 'PixelRebelz.Normal1zer.0': ['-1'] }

const text = (value) => (value === undefined || value === null ? '' : String(value).trim())

/**
 * 拆出合作画师：「A & B」各算一位。
 * 括号里的 & 属于画师署名本身（如「mology (青鸟&V17AMax Modified)」），不能拆，
 * 所以只在括号外遇到 & 才断开。
 */
export function splitIllustrators(name) {
  const parts = []
  let current = ''
  let depth = 0
  for (const ch of text(name)) {
    if ('(（[【'.includes(ch)) depth += 1
    else if (')）]】'.includes(ch)) depth = Math.max(0, depth - 1)
    if (ch === '&' && depth === 0) {
      parts.push(current)
      current = ''
      continue
    }
    current += ch
  }
  parts.push(current)
  return parts.map(text).filter(Boolean)
}

export function groupByIllustrator(songData, illVariantData) {
  const variantSongs = illVariantData?.songs || {}
  const grouped = {}

  /**
   * 一位画师一条：按「画师」列拆（如「57_dayo & AriaL & Stelli」算三位），
   * 「画师名义」是署名文字（如「57_dayo [edited by Stelli]」），不拆，只当卡片标题。
   */
  const add = (nominal, artist, item) => {
    if (PLACEHOLDER.test(nominal) || PLACEHOLDER.test(artist)) return
    for (const illustratorName of splitIllustrators(artist || nominal)) {
      if (!grouped[illustratorName]) grouped[illustratorName] = []
      grouped[illustratorName].push({
        ...item,
        illustrator: nominal || artist,
        artist: artist || nominal
      })
    }
  }

  for (const [songId, songInfo] of Object.entries(songData || {})) {
    if (HIDDEN_SONG_ID.test(songId)) continue
    const songName = songInfo?.name || ''
    const variants = variantSongs[songId]?.variants
    // 有多版曲绘的曲目：每一版单独成卡，画师与版本号都从 illvariants.json 取
    if (variants && Object.keys(variants).length) {
      for (const [variant, meta] of Object.entries(variants)) {
        // 和现用曲绘是同一张的旧图不列；只作用于画师列表，其他页面照旧
        if ((REPEATED_ART[songId] || []).includes(variant)) continue
        add(text(meta?.nominal), text(meta?.artist), {
          songId,
          name: songName,
          ill: Number(variant) || 0
        })
      }
      continue
    }
    add(text(songInfo?.illustrator), text(songInfo?.illustratorArtist), {
      songId,
      name: songName,
      ill: 0
    })
  }

  const sorted = {}
  for (const illustratorName of Object.keys(grouped).sort(compareNames)) {
    sorted[illustratorName] = grouped[illustratorName].sort(
      (a, b) => compareNames(a.name, b.name) || a.ill - b.ill
    )
  }
  return sorted
}
