<template>
  <div class="dt-page">
    <div class="illustrator-list">
      <section
        v-for="({ key: illustratorName, value: songList }, index) in sortedCardList"
        :id="`illustrator-${index}`"
        :key="illustratorName"
        class="illustrator-group"
      >
        <div class="dt-section__head">
          <h2 class="illustrator-title dt-title-bar">{{ illustratorName }}</h2>
        </div>
        <div class="card-grid" :style="getGridStyle()">
          <!-- 同一首歌的现用 / 历史 / 差分曲绘各是一张卡，曲绘按各自的版本取 -->
          <div
            v-for="item in songList"
            :key="`${item.songId}@${item.ill}`"
            class="chart-card"
            @click="openSong(item.songId)"
          >
            <div class="card-cover">
              <img :src="item.cover" :alt="item.name" class="cover-img" loading="lazy" />
            </div>
            <!-- 和谱师列表一样：大字是署名（画师名义），小字是本名（画师） -->
            <div class="card-info">
              <div class="info-title">{{ item.illustrator }}</div>
              <div class="info-sub">{{ item.artist }}</div>
            </div>
            <!-- 曲名压在曲绘上方但文字完全透明，看不见，只给浏览器 Ctrl+F 搜索定位 -->
            <span class="dt-cover-name">{{ item.name }}</span>
          </div>
        </div>
      </section>
    </div>
  </div>
</template>

<script setup>
import { computed, onMounted, onUnmounted, ref, defineProps, watch } from 'vue'
import { useOpenSong } from '../../api/openSong.js'
import { getIllustratorGroups } from '../../api/illustrators.js'
import { setAnchorNav, clearAnchorNav } from '../../composables/useAnchorNav.js'

const openSong = useOpenSong()

const illustratorList = ref(null)

onMounted(async () => {
  try {
    illustratorList.value = await getIllustratorGroups()
  } catch (error) {
    console.error('画师列表加载失败：', error)
  }
})

const props = defineProps({
  columns: {
    type: Number,
    default: 2
  },
  gap: {
    type: Number,
    default: 0.14
  }
})

const getGridStyle = () => ({
  '--column-count': props.columns,
  '--gap-rem': `${props.gap}rem`
})

const sortedCardList = computed(() => {
  if (!illustratorList.value) return []
  return Object.entries(illustratorList.value).map(([key, value]) => ({ key, value }))
})

// 每位画师登记成一个锚点（id 用序号，名字里可能有空格、括号等不合法字符）
watch(
  sortedCardList,
  (list) => {
    if (!list.length) {
      clearAnchorNav()
      return
    }
    setAnchorNav(
      list.map((group, index) => ({
        id: `illustrator-${index}`,
        label: group.key,
        icon: 'brush'
      }))
    )
  },
  { immediate: true }
)

onUnmounted(clearAnchorNav)


</script>

