/**
 * 名字排序：照 Windows 资源管理器里「名称」那一列的规则来。
 *
 * 1. 数字按数值比（2 在 10 前面）、英文不分大小写、中文按拼音 —— 交给 Intl.Collator；
 * 2. 再分三段：拉丁字母/数字、日文假名、汉字。只看名字的第一个字，
 *    这样「Daily天利」「knife美工刀」这类英文开头的仍在拉丁段，不会掉到中文末尾；
 * 3. 比较结果完全相同时（只差大小写）按原始码点定序，保证顺序稳定、可复现。
 *
 * 画师列表与谱师列表共用这一份，改排序只改这里。
 */

const collator = new Intl.Collator('zh-Hans-CN', { sensitivity: 'base', numeric: true })

const KANA = /[\p{Script=Hiragana}\p{Script=Katakana}]/u
const HAN = /\p{Script=Han}/u

/** 拉丁/数字 0、日文假名 1、汉字 2 */
const scriptRank = (name) => {
  const [first] = [...name]
  if (!first) return 0
  if (KANA.test(first)) return 1
  if (HAN.test(first)) return 2
  return 0
}

export const compareNames = (a, b) => {
  const byScript = scriptRank(a) - scriptRank(b)
  if (byScript) return byScript
  const byLocale = collator.compare(a, b)
  if (byLocale) return byLocale
  return a < b ? -1 : a > b ? 1 : 0
}
